class Solution {
    public String smallestGoodBase(String n) {
        long num = Long.parseLong(n);
        for (int m = (int)(Math.log(num) / Math.log(2)) + 1; m >= 2; m--) {
            long lo = 2, hi = (long) Math.pow(num, 1.0 / (m - 1)) + 1;
            while (lo <= hi) {
                long mid = lo + (hi - lo) / 2;
                long sum = 0, cur = 1;
                for (int i = 0; i < m; i++) { sum += cur; cur *= mid; }
                if (sum == num) return String.valueOf(mid);
                else if (sum < num) lo = mid + 1;
                else hi = mid - 1;
            }
        }
        return String.valueOf(num - 1);
    }
}
